diff --git a/test/functional/feature_assumeutxo.py b/test/functional/feature_assumeutxo.py
index 8727a9925e..67e0acc5b3 100755
--- a/test/functional/feature_assumeutxo.py
+++ b/test/functional/feature_assumeutxo.py
@@ -733,6 +733,11 @@ class AssumeutxoTest(BitcoinTestFramework):
         self.log.info("Check node2 updated the local services during snapshot load")
         self.assert_only_network_limited_service(n2)

+        self.log.info("Verify snapshot tip with default checks before background validation reaches it")
+        n2.submitblock(snapshot_block)
+        with n2.assert_debug_log(expected_msgs=["Verifying last 6 blocks at level 3", f"Block verification stopping at height {SNAPSHOT_BASE_HEIGHT} (no undo data)."]):
+            assert_equal(n2.verifychain(), False)
+
         for reindex_arg in ['-reindex=1', '-reindex-chainstate=1']:
             self.log.info(f"Check that restarting with {reindex_arg} will delete the snapshot chainstate")
             self.restart_node(2, extra_args=[reindex_arg, *self.extra_args[2]])
diff --git a/test/functional/rpc_getblockfrompeer.py b/test/functional/rpc_getblockfrompeer.py
index f646abed01..992c1cea1a 100755
--- a/test/functional/rpc_getblockfrompeer.py
+++ b/test/functional/rpc_getblockfrompeer.py
@@ -155,6 +155,21 @@ class GetBlockFromPeerTest(BitcoinTestFramework):
         assert_equal(pruned_node.pruneblockchain(1000), pruneheight)
         assert_raises_rpc_error(-1, "Block not available (pruned data)", pruned_node.getblock, pruned_block)

+        self.log.info("Verify a refetched pruned block without undo")
+        # Restore the highest pruned block so verification reaches it before any missing block bodies
+        refetched_block = self.nodes[0].getblockhash(pruneheight)
+        pruned_node.getblockfrompeer(refetched_block, pruned_node_peer_0_id)
+        self.wait_until(lambda: self.check_for_block(node=2, hash=refetched_block))
+        verification_msg = f"Block verification stopping at height {pruneheight} (no undo data)."
+        check_depth = pruned_node.getblockcount() - pruneheight + 1
+        assert_equal(pruned_node.verifychain(2, check_depth), True)
+        with pruned_node.assert_debug_log(expected_msgs=[verification_msg]):
+            assert_equal(pruned_node.verifychain(4, check_depth), False)
+        with pruned_node.assert_debug_log(expected_msgs=[verification_msg]):
+            self.restart_node(2, extra_args=self.extra_args[2] + ["-checkblocks=0", "-checklevel=4"])
+        assert_equal(pruned_node.getbestblockhash(), self.nodes[0].getbestblockhash())
+        assert_equal(pruned_node.getblock(refetched_block)["hash"], refetched_block)
+

 if __name__ == '__main__':
     GetBlockFromPeerTest(__file__).main()
diff --git a/src/validation.cpp b/src/validation.cpp
index 9d1e1e3563..9e90de9a78 100644
--- a/src/validation.cpp
+++ b/src/validation.cpp
@@ -4648,11 +4648,11 @@ VerifyDBResult CVerifyDB::VerifyDB(
     int nGoodTransactions = 0;
     BlockValidationState state;
     int reportDone = 0;
-    bool skipped_no_block_data{false};
+    bool skipped_missing_data{false};
     bool skipped_l3_checks{false};
     LogInfo("Verification progress: 0%%");

-    const bool is_snapshot_cs{chainstate.m_from_snapshot_blockhash};
+    const bool allow_missing_data{chainstate.m_blockman.IsPruneMode() || chainstate.m_from_snapshot_blockhash};

     for (pindex = chainstate.m_chain.Tip(); pindex && pindex->pprev; pindex = pindex->pprev) {
         const int percentageDone = std::max(1, std::min(99, (int)(((double)(chainstate.m_chain.Height() - pindex->nHeight)) / (double)nCheckDepth * (nCheckLevel >= 4 ? 50 : 100))));
@@ -4665,11 +4665,11 @@ VerifyDBResult CVerifyDB::VerifyDB(
         if (pindex->nHeight <= chainstate.m_chain.Height() - nCheckDepth) {
             break;
         }
-        if ((chainstate.m_blockman.IsPruneMode() || is_snapshot_cs) && !(pindex->nStatus & BLOCK_HAVE_DATA)) {
+        if (allow_missing_data && !(pindex->nStatus & BLOCK_HAVE_DATA)) {
             // If pruning or running under an assumeutxo snapshot, only go
             // back as far as we have data.
             LogInfo("Block verification stopping at height %d (no data). This could be due to pruning or use of an assumeutxo snapshot.", pindex->nHeight);
-            skipped_no_block_data = true;
+            skipped_missing_data = true;
             break;
         }
         CBlock block;
@@ -4698,6 +4698,12 @@ VerifyDBResult CVerifyDB::VerifyDB(
         size_t curr_coins_usage = coins.DynamicMemoryUsage() + chainstate.CoinsTip().DynamicMemoryUsage();

         if (nCheckLevel >= 3) {
+            // A block refetched after pruning has its body but not its undo data
+            if (allow_missing_data && !(pindex->nStatus & BLOCK_HAVE_UNDO)) {
+                LogInfo("Block verification stopping at height %d (no undo data). This could be due to pruning or use of an assumeutxo snapshot.", pindex->nHeight);
+                skipped_missing_data = true;
+                break;
+            }
             if (curr_coins_usage <= chainstate.m_coinstip_cache_size_bytes) {
                 assert(coins.GetBestBlock() == pindex->GetBlockHash());
                 DisconnectResult res = chainstate.DisconnectBlock(block, pindex, coins);
@@ -4760,7 +4766,7 @@ VerifyDBResult CVerifyDB::VerifyDB(
     if (skipped_l3_checks) {
         return VerifyDBResult::SKIPPED_L3_CHECKS;
     }
-    if (skipped_no_block_data) {
+    if (skipped_missing_data) {
         return VerifyDBResult::SKIPPED_MISSING_BLOCKS;
     }
     return VerifyDBResult::SUCCESS;

